$template = Get-Content -Raw "template.html"

Function Generate-Package {
    param($filename, $title, $duration, $region, $places, $type, $bg, $overview, $price, $price_tax, $departing, $cities, $itinerary)

    $city_widgets = ""
    foreach ($c in $cities) {
        $cName = $c.Name
        $cNights = $c.Nights
        $city_widgets += "<div style='flex:1; text-align:center; min-width:80px;'><div style='font-size:1.6rem; margin-bottom:6px;'>📍</div><div style='font-weight:700; color:var(--navy); font-size:0.9rem;'>$cName</div><div style='font-size:0.78rem; color:var(--text-light);'>$cNights</div></div>"
    }

    $itinerary_html = ""
    $day = 1
    foreach ($i in $itinerary) {
        $iTitle = $i.Title
        $iDest = $i.Dest
        $iContent = $i.Content
        $itinerary_html += "<div class='itinerary-item'><div class='day-marker'>$day</div><div class='day-header'><h3 class='day-title'>$iTitle</h3><span class='day-dest'>$iDest</span></div><div class='day-content'>$iContent</div></div>"
        $day++
    }

    $html = $template.Replace("{{package_title}}", $title).Replace("{{duration}}", $duration).Replace("{{region}}", $region).Replace("{{places}}", $places).Replace("{{type}}", $type).Replace("{{bg_image}}", $bg).Replace("{{overview}}", $overview).Replace("{{city_widgets}}", $city_widgets).Replace("{{itinerary_html}}", $itinerary_html).Replace("{{price}}", $price).Replace("{{price_tax}}", $price_tax).Replace("{{departing}}", $departing)

    [System.IO.File]::WriteAllText("c:\Users\sai\Desktop\travelspark\packages\$filename", $html, [System.Text.Encoding]::UTF8)
    Write-Host "Created $filename"
}

Generate-Package -filename "andaman-package.html" -title "Enchanting Andaman" -duration "5 Nights / 6 Days" -region "Andaman" -places "Port Blair, Havelock" -type "Beaches Leisure" -bg "https://images.unsplash.com/photo-1588602641570-5b5ea6c4bcba?w=1800" -overview "Experience the pristine beaches, azure waters, and rich colonial history of the Andaman Islands. This 6-day tour covers the top attractions in Port Blair and the breathtaking Radhanagar Beach in Havelock Island." -price "On Request" -price_tax "Per Person on Twin Sharing Excl. 5% GST" -departing "Port Blair" -cities @(@{Name="Port Blair"; Nights="3 Nights"},@{Name="Havelock"; Nights="2 Nights"}) -itinerary @(@{Title="Arrival at Port Blair"; Dest="Port Blair"; Content="Arrive in Port Blair, the capital city. Check into your hotel. In the afternoon, visit the historic Cellular Jail followed by the moving Light Sound Show in the evening. Overnight at Port Blair."},@{Title="Port Blair to Havelock - Radhanagar Beach"; Dest="Havelock"; Content="Post breakfast, board a ferry to Havelock Island. Check-in to your hotel. Visit the world-famous Radhanagar Beach, known for its white sand and breathtaking sunset. Overnight at Havelock."},@{Title="Elephant Beach Excursion"; Dest="Havelock"; Content="Morning trip to Elephant Beach, famous for its coral reefs and water sports. Enjoy snorkeling. Return to hotel. Overnight at Havelock."},@{Title="Return to Port Blair"; Dest="Port Blair"; Content="Check out from Havelock and board the ferry back to Port Blair. Evening at leisure for shopping or relaxing at the hotel. Overnight at Port Blair."},@{Title="Ross Island"; Dest="Port Blair"; Content="Enjoy a full-day excursion to Ross Island and North Bay (Coral Island) offering excellent snorkeling opportunities. Overnight at Port Blair."},@{Title="Departure"; Dest="Port Blair"; Content="After breakfast, check out from the hotel and proceed to the airport for your return flight with infinite memories of the islands."})

