Generate-Package -filename "essence-of-kerala.html" -title "Essence of Kerala" -duration "4 Nights / 5 Days" -region "Kerala" -places "Munnar, Thekkady, Alleppey" -type "Family Nature" -bg "https://images.unsplash.com/photo-1602216056096-3b40cc0c9944?w=1800" -overview "Discover the true essence of Gods Own Country. Wind through the sprawling tea gardens of Munnar, experience the spice plantations and wildlife of Thekkady, and cruise the tranquil backwaters of Alleppey in your private houseboat." -price "On Request" -price_tax "Per Person on Twin Sharing Excl. 5% GST" -departing "Kochi (Cochin)" -cities @(@{Name="Munnar"; Nights="2 Nights"},@{Name="Thekkady"; Nights="1 Night"},@{Name="Alleppey"; Nights="1 Night"}) -itinerary @(@{Title="Arrival at Cochin Drive to Munnar"; Dest="Munnar"; Content="Arrive at Cochin Airport/Station. Meet our representative and drive to Munnar, enjoying scenic waterfalls and tea gardens en route. Check-in to the hotel. Overnight stay at Munnar."},@{Title="Munnar Sightseeing"; Dest="Munnar"; Content="Post breakfast, go for a full day sightseeing of Munnar. Visit Mattupetty Dam, Echo Point, Tea Museum, and Eravikulam National Park. Return to hotel for overnight stay."},@{Title="Munnar to Thekkady"; Dest="Thekkady"; Content="Drive to Thekkady. Check-in to your hotel. Later, visit spice plantations or take an optional boat ride in Periyar Lake to spot wildlife. Overnight stay at Thekkady."},@{Title="Thekkady to Alleppey (Houseboat)"; Dest="Alleppey"; Content="Drive to Alleppey, the Venice of the East. Board your traditional houseboat at noon. Enjoy a scenic cruise through the backwaters, taking in village life. Meals served on board. Overnight stay in Houseboat."},@{Title="Departure from Cochin"; Dest="Cochin"; Content="After breakfast on the houseboat, disembark and drive back to Cochin for your return flight/train journey."})

